package ui

import (
	"github.com/ayn2op/tview"
)

// Response is a collection of [tview.Msg]s and [tview.Cmd]s that
// were generated by child models in response to an event or message
// from the parent.
type Response struct {
	msgs []tview.Msg
	cmds []tview.Cmd

	msgIdxStart, msgIdxEnd int
}

// NewResponse returns a new [Response] collection.
// This is to be used by the parent model, and the
// returned [*Response] should be passed to all child
// models, which append messages and commands to it
// for them to be processed by the parent model.
func NewResponse() *Response {
	return &Response{}
}

// PushMsg appends a [tview.Msg] to the collection.
func (r *Response) PushMsg(msg tview.Msg) {
	if msg == nil {
		return
	}

	r.msgs = append(r.msgs, msg)
}

// PushRouted appends a routed message to the collection.
func (r *Response) PushRouted(msg Router) {
	if msg == nil {
		return
	}

	r.msgs = append(r.msgs, msg)
}

// PushCmd appends a [tview.Cmd] to the collection.
func (r *Response) PushCmd(cmd tview.Cmd) {
	if cmd == nil {
		return
	}

	r.cmds = append(r.cmds, cmd)
}

// Msgs returns the messages that were generated by the
// child models.
func (r *Response) Msgs() ([]tview.Msg, bool) {
	if len(r.msgs) <= r.msgIdxEnd {
		return nil, false
	}

	r.msgIdxStart = max(r.msgIdxEnd-1, 0)
	r.msgIdxEnd = len(r.msgs)

	return r.msgs[r.msgIdxStart:r.msgIdxEnd], true
}

// Cmds returns the list of [tview.Cmd]s that need to be processed.
func (r *Response) Cmds() tview.Cmd {
	if r.cmds == nil {
		return nil
	}

	if len(r.cmds) == 1 {
		return r.cmds[0]
	}

	return tview.Batch(r.cmds...)
}
